const rt=fr(R,"tabs",{width:"fill_container",padding:[0,12],gap:2,stroke:"$border",strokeWidth:{bottom:1}});for(const [l,a] of [["Loop",1],["Style",0],["Conditions",0],["Attributes",0]]){const t=fr(rt,"T "+l,{layout:"vertical"});const lb=fr(t,"l",{padding:[10,8]});tx(lb,l,{fontSize:12,fontWeight:"500",fill:a?"$fg":"$muted-fg"});fr(t,"u",{width:"fill_container",height:2,...(a?{fill:"$primary"}:{})});}
