for(const [a,b,c] of [["Status","is","Published"],["Recipe › Difficulty","equals","Easy"],["Published date","within","last 12 months"]]){const fl=fr(s3,"F "+a,{width:"fill_container",padding:[6,8],gap:6,cornerRadius:8,stroke:"$border",strokeWidth:1,fill:"$bg",alignItems:"center"});tx(fl,a,{fontSize:12,fontWeight:"500"});tx(fl,b,{fontSize:12,fill:"$muted-fg"});tx(fl,c,{fontSize:12,fontWeight:"500",fill:c=="current Entry"?"$primary":"$fg"});sp(fl);ic(fl,"x",{width:12,height:12});}
