for(const [p,f] of [["title","Title"],["image","Cover image"],["byline","Written by › Title"],["date","Published date"]]){const rw=fr(s6,"Prop "+p,{width:"fill_container",gap:8,alignItems:"center"});const pc=fr(rw,"p",{width:70});tx(pc,p,{fontSize:12,fontFamily:"Geist Mono",fill:"$muted-fg"});ic(rw,"arrow-left",{width:12,height:12});const fv=fr(rw,"v",{width:"fill_container",padding:[4,8],cornerRadius:6,stroke:"$border",strokeWidth:1,fill:"$bg",gap:6,alignItems:"center"});ic(fv,"database",{width:11,height:11,fill:"$brand"});tx(fv,f,{fontSize:12});}
